#include <FastLED.h>
#define NUM_LEDS 157
#define DATA_PIN 25
#define MAX_FRAMES 156

CRGB leds[NUM_LEDS];
int frameIndex = 0;
int column = 0; //we have 6 columns
int animation = 0; //index for tracking what animation is running 
static uint32_t lastStep = 0;

void setup() {
  FastLED.addLeds<WS2812, DATA_PIN>(leds, NUM_LEDS);
  FastLED.setBrightness(10);
  FastLED.clear();
  makeStripes();
}

void loop() {
  if (millis() - lastStep >= 5000) {
    lastStep = millis();
    animation++;
    animation = animation%2;
  }
  switch(animation){
    case 0:
      caneChase();
      break;
    case 1:
      sparkle();
      break;
    case 2:
      verticalBeam();
      break;
  }

}

